<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;

trait UserRoleAssignmentRolesRoleAttributeHolder
{
    protected UserRoleAssignmentRolesRoleVO|RoleRef|null $role = null;
    protected bool $roleAssigned = false;

    public function getRoleOrCurrent(UserRoleAssignmentRolesRoleVO $role): UserRoleAssignmentRolesRoleVO
    {
        if ($this->roleAssigned) {
            \assert(null !== $this->role);
            return UserRoleAssignmentRolesRoleVO::from($this->role);
        } else {
            return $role;
        }
    }
    public function roleTryBuildInitial(ConstraintFailList $error): ?UserRoleAssignmentRolesRoleVO
    {
        return  UserRoleAssignmentRolesRoleVO::tryFrom($this->roleAssigned ? $this->role : null, $error);
    }
    public function role(UserRoleAssignmentRolesRoleVO|RoleRef $role): static
    {
        $this->role = $role;
        $this->roleAssigned = true;
        return $this;
    }
    public function getRole(): ?RoleRef
    {
        return $this->role instanceof UserRoleAssignmentRolesRoleVO ? $this->role->value() : $this->role;
    }
    public function isRoleAssigned(): bool
    {
        return $this->roleAssigned;
    }
    public function writeRoleTo(mixed $att): void
    {
        if ($this->roleAssigned) {
            \assert(null !== $this->role);
            $att->role($this->role);
        }
    }
    public function readRoleFrom(mixed $att): void
    {
        if ($att->isRoleAssigned()) {
            $role = $att->getRole();
            \assert(null !== $role);
            $this->role($role);
        }
    }
    public function unsetRole(): static
    {
        $this->roleAssigned = false;
        return $this;
    }
    protected function withDefaultRole(): void
    {
    }
    protected function withAssertedRoleRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->roleAssigned = $this->roleAssigned) {
            $value->role = UserRoleAssignmentRolesRoleVO::tryFrom($this->role, $errorsList);
        }
    }
}
